def unique(items):
    """Removes duplicates from a list."""
    return sorted(set(items))

files.tests/test_dedupe.py:
from dedupe import unique


def test_removes_duplicates():
    assert unique([1, 1, 2]) == [1, 2]


def test_empty():
    assert unique([]) == []


def test_keeps_first_seen_order_for_ordered_input():
    assert unique([1, 2, 3, 1]) == [1, 2, 3]


def test_unique_single_item():
    assert unique([5]) == [5]

